import org.junit.Test;
import static org.junit.Assert.*;
import org.apache.commons.lang.StringUtils;

public class StringUtilsContainsIgnoreCaseTest {

    @Test
    public void testContainsIgnoreCase() {
        // R3: A null String or null search String will return false.
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
        assertFalse(StringUtils.containsIgnoreCase(null, null));

        // R3: An empty search String ("") is considered to be contained within any non-null String, including an empty String.
        assertTrue(StringUtils.containsIgnoreCase("", "")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("abc", "")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("ABC", ""));
        assertTrue(StringUtils.containsIgnoreCase("aBc", ""));

        // R2: agreement with contains when case does not matter
        assertTrue(StringUtils.containsIgnoreCase("abc", "abc"));
        assertTrue(StringUtils.contains("abc", "abc"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "def"));
        assertFalse(StringUtils.contains("abc", "def"));

        // R4: Case-insensitive check
        assertTrue(StringUtils.containsIgnoreCase("abc", "a")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("abc", "A")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("ABC", "a"));
        assertTrue(StringUtils.containsIgnoreCase("aBc", "B"));
        assertTrue(StringUtils.containsIgnoreCase("aBc", "bC"));
        assertTrue(StringUtils.containsIgnoreCase("aBc", "BC"));

        // R4: Not found
        assertFalse(StringUtils.containsIgnoreCase("abc", "z")); // from Javadoc
        assertFalse(StringUtils.containsIgnoreCase("abc", "Z")); // from Javadoc
        assertFalse(StringUtils.containsIgnoreCase("ABC", "z"));
        assertFalse(StringUtils.containsIgnoreCase("aBc", "xY"));

        // R4: Longer search string
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcd"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "ABCD"));

        // R4: String with special characters
        assertTrue(StringUtils.containsIgnoreCase("aB-c", "b-"));
        assertTrue(StringUtils.containsIgnoreCase("aB-c", "B-C"));
        assertFalse(StringUtils.containsIgnoreCase("aB-c", "b_"));

        // R4: Empty string as str
        assertFalse(StringUtils.containsIgnoreCase("", "a"));
        assertFalse(StringUtils.containsIgnoreCase("", "A"));

        // R4: Search string same as str, different case
        assertTrue(StringUtils.containsIgnoreCase("Test", "test"));
        assertTrue(StringUtils.containsIgnoreCase("test", "Test"));

        // R4: Multiple occurrences, first one matches case-insensitively
        assertTrue(StringUtils.containsIgnoreCase("banana", "ANA"));
        assertTrue(StringUtils.containsIgnoreCase("Banana", "ana"));

        // R4: Substring at the beginning
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "hello"));
        assertTrue(StringUtils.containsIgnoreCase("helloworld", "Hello"));

        // R4: Substring at the end
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "world"));
        assertTrue(StringUtils.containsIgnoreCase("helloworld", "World"));

        // R4: Substring in the middle
        assertTrue(StringUtils.containsIgnoreCase("HelloWorld", "lowo"));
        assertTrue(StringUtils.containsIgnoreCase("helloworld", "LOWO"));
    }
}
